"""Current controller workflows and MK3-only wording, for EN/DE manuals."""

def enrich(chapters,lang='en'):
    de=lang=='de'
    text=lambda en,deutsch:deutsch if de else en
    by={c.get('source_title',c['title']):c for c in chapters}
    ch=by['Select and edit individual events']
    ch['steps'][0]=dict(mikro=text('Open PATTERN and press ENTER, or use SHIFT + SELECT. F1 switches between Sound rows and pitches.','Öffne PATTERN und drücke ENTER oder nutze SHIFT + SELECT. F1 wechselt zwischen Sound-Zeilen und Tonhöhen.'),mk2=text('Open PATTERN and use EDITOR, or use SHIFT + SELECT. Sound rows run from pad 1 at the bottom to pad 16 at the top.','Öffne PATTERN mit EDITOR oder nutze SHIFT + SELECT. Die Sound-Zeilen laufen von Pad 1 unten bis Pad 16 oben.'),mk3=text('Press EVENTS to open the editor, or use SHIFT + SELECT. Sound rows run from pad 1 at the bottom to pad 16 at the top.','Drücke EVENTS oder nutze SHIFT + SELECT zum Öffnen des Editors. Die Sound-Zeilen laufen von Pad 1 unten bis Pad 16 oben.'))
    ch['steps'][2]=dict(mikro=text('At an empty cursor position, F3 or ENTER inserts a note and opens editing. At existing notes it opens editing of the cursor target or selected set. Arrows choose POSITION, NOTE, VELOCITY, PROBABILITY or LENGTH.','An einer leeren Cursorposition setzt F3 oder ENTER eine Note und öffnet die Bearbeitung. Bei vorhandenen Noten öffnet sich das Cursorziel oder die markierte Menge. Die Pfeile wählen POSITION, NOTE, VELOCITY, PROBABILITY oder LENGTH.'),mk2=text('EDIT opens the marked notes; ADD NOTE inserts at an empty cursor position. SELECTED highlights the cursor selection. Use the encoders under POSITION, PITCH, VELOCITY, PROBABILITY and LENGTH. DONE returns to the grid.','EDIT öffnet die markierten Noten; ADD NOTE setzt an einer leeren Cursorposition eine Note. SELECTED hebt die Cursorauswahl hervor. Nutze die Encoder unter POSITION, PITCH, VELOCITY, PROBABILITY und LENGTH. DONE kehrt zum Raster zurück.'))
    ch['notes'][1]=(text('Follow and stop position','Follow und Stop-Position'),dict(mikro=text('Moving the cursor pauses Follow. SHIFT + F1, or VIEW > GRID > FOLLOW, enables it again. The playhead remains at the stopped position.','Bewegen des Cursors pausiert Follow. SHIFT + F1 oder VIEW > GRID > FOLLOW aktiviert es wieder. Der Playhead bleibt an der gestoppten Position stehen.'),mk2=text('Moving the cursor pauses Follow. Display button 3 FOLLOW enables it again. The playhead remains visible at the stopped position; RESTART returns to the beginning.','Bewegen des Cursors pausiert Follow. Displaytaste 3 FOLLOW aktiviert es wieder. Der Playhead bleibt an der gestoppten Position sichtbar; RESTART springt zum Anfang.'),mk3=text('Moving the cursor pauses Follow. Press FOLLOW or display button 3 FOLLOW to enable it again. The stopped playhead shows the transport position. RESTART returns to the beginning.','Bewegen des Cursors pausiert Follow. FOLLOW oder Displaytaste 3 FOLLOW aktiviert es wieder. Der angehaltene Playhead zeigt die Transportposition. RESTART springt zum Anfang.')))
    ch.setdefault('supplements',[]).append(dict(title=text('Events: select a time range','Events: einen Zeitbereich auswählen'),intro=text('A time selection contains notes from the selected Sound/pad only. In Keyboard mode it includes all pitches of that Sound inside the range. Other pads are excluded.','Eine Bereichsauswahl enthält ausschließlich Noten des ausgewählten Sounds/Pads. Im Keyboard-Modus umfasst sie alle Tonhöhen dieses Sounds im Bereich. Andere Pads bleiben ausgeschlossen.'),figures=['Tutorial / Events range'],steps=[dict(mikro=text('Choose the Sound/pad first. Hold the physical SELECT button and turn the encoder forwards or backwards from the time cursor.','Wähle zuerst den Sound/das Pad. Halte die physische SELECT-Taste und drehe den Encoder vom Zeitcursor aus vor oder zurück.'),mk2=text('Choose the Sound/pad first. Hold physical SELECT or display button 1 SELECT. Turn the selection/master encoder, EVENT or POSITION to grow the time range.','Wähle zuerst den Sound/das Pad. Halte die physische SELECT-Taste oder Displaytaste 1 SELECT. Drehe den Auswahl-/Master-Encoder, EVENT oder POSITION, um den Bereich zu erweitern.'),mk1=text('Choose the Sound/pad first. Hold physical SELECT or display button 1 SELECT and turn encoder 1 EVENT or encoder 5 POSITION to grow the range.','Wähle zuerst den Sound/das Pad. Halte die physische SELECT-Taste oder Displaytaste 1 SELECT und drehe Encoder 1 EVENT oder Encoder 5 POSITION zum Erweitern.'),mk3=text('Choose the Sound/pad first. Hold physical SELECT or display button 1 SELECT. Turn the 4D encoder, encoder 1 EVENT or encoder 5 POSITION to grow the range.','Wähle zuerst den Sound/das Pad. Halte die physische SELECT-Taste oder Displaytaste 1 SELECT. Drehe den 4D-Encoder, Encoder 1 EVENT oder Encoder 5 POSITION zum Erweitern.')),text('Turn back to shrink the range. Release SELECT to retain the selected notes. Marked notes have an outline; merely selecting does not change note data.','Drehe zurück zum Verkleinern. Lass SELECT los, um die markierten Noten beizubehalten. Markierte Noten sind umrandet; Auswählen allein ändert keine Notendaten.'),text('EDIT changes the selected set together. To delete it, press ERASE and confirm. NONE clears the selection; tapping the SELECT display action toggles only the cursor notes.','EDIT bearbeitet die markierte Menge gemeinsam. ERASE mit Bestätigung löscht sie. NONE hebt die Auswahl auf; kurzes Drücken der Displayaktion SELECT schaltet nur die Noten am Cursor um.')],notes=[]))
    ch=by['Keyboard, scales and 16 velocities']
    ch['notes'].append((text('Pitch display','Tonhöhenanzeige'),text('The display uses note names, with C3 corresponding to MIDI 60. On a fresh Sound the keyboard starts at C3. The keyboard drawing follows the last played note or chord and keeps that focus after release.','Die Anzeige nutzt Notennamen; C3 entspricht MIDI 60. Bei einem neuen Sound beginnt Keyboard bei C3. Die Klaviaturgrafik folgt der zuletzt gespielten Note oder dem Akkord und behält den Fokus nach dem Loslassen.')))
    ch=by['Reading the displays']
    ch['notes'].append((text('Instrument and effect overview','Instrument- und Effektübersicht'),dict(mikro=text('The first PLUG-IN page shows a small instrument/effect icon and its patch or effect name. Long names start scrolling after two seconds; the icon, page count and parameter value stay fixed. Waveforms, meters and detailed parameter graphs keep their own space.','Die erste PLUG-IN-Seite zeigt ein kleines Instrument-/Effekticon und den Patch- oder Effektnamen. Lange Namen laufen nach zwei Sekunden durch; Icon, Seitenzahl und Parameterwert bleiben stehen. Wellenformen, Pegel und detaillierte Parametergrafiken behalten ihren Platz.'),mk1=text('The first PLUG-IN page shows the selected instrument/effect icon. BANK and PATCH numbers stay on the left; names stay on the right. CHANNEL keeps sample waveforms or shows the instrument/effect picture below the Sound name.','Die erste PLUG-IN-Seite zeigt das Icon des gewählten Instruments/Effekts. BANK- und PATCH-Nummern bleiben links, die Namen rechts. CHANNEL behält Sample-Wellenformen oder zeigt das Instrument-/Effektbild unter dem Sound-Namen.'),mk2=text('The first PLUG-IN page shows the selected instrument/effect icon. BANK and PATCH numbers stay on the left; names stay on the right. CHANNEL keeps sample waveforms or shows the instrument/effect picture below the Sound name.','Die erste PLUG-IN-Seite zeigt das Icon des gewählten Instruments/Effekts. BANK- und PATCH-Nummern bleiben links, die Namen rechts. CHANNEL behält Sample-Wellenformen oder zeigt das Instrument-/Effektbild unter dem Sound-Namen.'),mk3=text('The first PLUG-IN page shows the selected chain slot as an instrument/effect card. The slot number and arrows identify its position in the chain. Following parameter pages use both displays.','Die erste PLUG-IN-Seite zeigt den gewählten Chain-Slot als Instrument-/Effektkarte. Slot-Nummer und Pfeile zeigen die Position in der Chain. Die folgenden Parameterseiten nutzen beide Displays.'))))
    for device in ('mk1','mk2','mk3'):
        if device!='mk3':
            ch['notes'][-1][1][device]+=text(' Parameter pages show eight labelled fill bars on the right, in two columns. The numbers 1-8 identify the physical encoders. Numeric values remain in the bottom encoder fields; the bar overview does not repeat percentages.',' Parameterseiten zeigen rechts acht beschriftete Füllbalken in zwei Spalten. Die Nummern 1-8 bezeichnen die physischen Encoder. Zahlenwerte stehen weiterhin in den unteren Encoderfeldern; die Balkenübersicht wiederholt keine Prozentangaben.')
            continue
        ch['notes'][-1][1][device]+=text(' Parameter pages show all eight encoder values on the right, in two columns with compact numeric readouts. The numbers 1-8 identify the physical encoders; the bottom fields keep their usual assignments.',' Parameterseiten zeigen rechts alle acht Encoderwerte in zwei Spalten mit kompakten Zahlen. Die Nummern 1-8 bezeichnen die physischen Encoder; die unteren Felder behalten ihre gewohnte Zuordnung.')
    ch=by['Navigation, hold and pin']
    ch['notes'].append((text('Channel default','Channel-Standardseite'),dict(mikro=text('When switching from PLUG-IN to CHNL with NAV + F2, OUTPUT is selected by default. Turn the encoder while holding NAV to choose INPUT, GROOVE or MACRO explicitly. The page counter refers only to the selected module or compact plug-in pages.','Beim Wechsel von PLUG-IN zu CHNL mit NAV + F2 wird standardmäßig OUTPUT gewählt. Drehe den Encoder bei gehaltenem NAV, um INPUT, GROOVE oder MACRO gezielt zu wählen. Die Seitenzahl bezieht sich nur auf das gewählte Modul beziehungsweise die kompakten Plug-in-Seiten.'),mk1='',mk2='',mk3='')))
    # Native sampling and effect features remain accessible without external plugins.
    ch=by['Channel routing and the Mixer']
    ch.setdefault('supplements',[]).append(dict(title=text('Ducktor: sidechain ducking','Ducktor: Sidechain-Ducking'),intro=text('Ducktor is a built-in effect. Insert it on a bass Sound, Group or other target and use another signal, such as a kick, to reduce its level rhythmically.','Ducktor ist ein eingebauter Effekt. Setze ihn auf einen Bass-Sound, eine Group oder ein anderes Ziel und nutze ein Signal wie eine Kick zum rhythmischen Absenken.'),figures=['Tutorial / Ducktor'],steps=[text('On the target, open an empty effect slot and load Ducktor / Sidechain Ducker. Set SOURCE to the trigger Sound, Group or EXT STEREO. Invalid feedback routes are excluded.','Öffne am Ziel einen leeren Effekt-Slot und lade Ducktor / Sidechain Ducker. SOURCE wählt den Trigger-Sound, die Group oder EXT STEREO. Ungültige Rückkopplungswege sind ausgeschlossen.'),text('Play the trigger and target. Lower THRESHOLD until the GR meter shows reduction. Set ATTACK, RELEASE, MAX DUCK and MIX to taste. The second page contains KNEE, HOLD and DETECT HP.','Spiele Trigger und Ziel. Senke THRESHOLD, bis GR die Absenkung zeigt. Stelle ATTACK, RELEASE, MAX DUCK und MIX ein. Die zweite Seite enthält KNEE, HOLD und DETECT HP.'),text('Save the project or Sound to preserve the source and controls. Muting the trigger also removes its audio trigger; this implementation has no separate ghost-trigger mode.','Speichere Project oder Sound zum Erhalten von Quelle und Werten. Muten des Triggers entfernt auch dessen Audiosignal; ein separater Ghost-Trigger-Modus ist nicht vorhanden.')],notes=[]))
    ch=by['Sounds, Zones and Autosampler']
    ch.setdefault('supplements',[]).append(dict(title=text('SoundFonts as native Sounds','SoundFonts als native Sounds'),intro=text('The WebUI imports uncompressed SoundFont 2 (.sf2) presets into native sampler Sounds. No external playback plugin is required. SF3 is not supported.','Die WebUI importiert Presets aus unkomprimierten SoundFont-2-Dateien (.sf2) als native Sampler-Sounds. Ein externes Wiedergabe-Plug-in wird nicht benötigt. SF3 wird nicht unterstützt.'),steps=[text('Open Sounds in the WebUI and choose Import SoundFont. Upload an .sf2 file, then inspect its preset list. Choose the bank and preset you want to convert.','Öffne Sounds in der WebUI und wähle Import SoundFont. Lade eine .sf2-Datei hoch und prüfe ihre Preset-Liste. Wähle Bank und Preset zum Konvertieren.'),text('Review compatibility notes before import. Name the Sound, choose its folder and tags, then import. Native zones preserve supported samples, key/velocity ranges and playback mapping.','Prüfe vor dem Import die Kompatibilitätshinweise. Vergib Sound-Namen, Ordner und Tags und importiere. Native Zonen übernehmen unterstützte Samples, Tasten-/Velocity-Bereiche und Wiedergabezuordnungen.'),text('Load the result from Sounds on the controller and play it in Keyboard mode. Compare envelopes and balance: custom SF2 modulators and some filter/effect behavior are not reproduced.','Lade das Ergebnis am Controller aus Sounds und spiele es im Keyboard-Modus. Prüfe Hüllkurven und Balance: Eigene SF2-Modulatoren und manche Filter-/Effektfunktionen werden nicht nachgebildet.')],notes=[],figures=[]))
    # These dedicated actions have no other-controller wording in the MK3 guide.
    c=by['Know your controller'];c['intro']['mk3']=text('The MK3 has two 480 x 272 color displays, eight display buttons, eight parameter encoders and a 4D push encoder. Dedicated mode buttons and a Smart Strip provide direct performance controls.','Die MK3 besitzt zwei Farbdisplays mit je 480 x 272 Pixeln, acht Displaytasten, acht Parameter-Encoder und einen drückbaren 4D-Encoder. Eigene Modustasten und der Smart Strip ermöglichen direkten Zugriff beim Spielen.')
    c['notes'][2][1]['mk3']=text('CHANNEL and PLUG-IN open channel/instrument controls; SETTINGS opens settings. MIXER, ARRANGER and EVENTS open their workspaces directly. VARIATION opens Navigate: choose a highlighted icon, then release to enter. Select the same icon again to return.','CHANNEL und PLUG-IN öffnen Channel-/Instrument-Parameter; SETTINGS öffnet die Einstellungen. MIXER, ARRANGER und EVENTS öffnen ihre Arbeitsbereiche direkt. VARIATION öffnet Navigate: Symbol markieren und zum Öffnen loslassen. Dasselbe Symbol erneut wählen zum Zurückkehren.')
    c['notes'][-1][1]['mk3']=text('Turn the 4D encoder to select, press it to confirm. In Events, push up/down to change the focused row or pitch. PITCH, MOD and NOTES select Smart Strip behavior; PERFORM opens Live FX.','Drehe den 4D-Encoder zum Auswählen und drücke ihn zum Bestätigen. In Events wählt Auf/Ab die Zeile oder Tonhöhe. PITCH, MOD und NOTES wählen die Smart-Strip-Funktion; PERFORM öffnet Live FX.')
    c=by['Setup and first start'];c['steps'][1]=dict(mikro=c['steps'][1],mk2=c['steps'][1],mk3=text('Insert the card, connect the MK3 and an audio output, then power the Pi. Machinista opens the control view on both color displays. Allow about two minutes for first-boot expansion and a possible restart.','Setze die Karte ein, verbinde MK3 und Audioausgang und schalte den Pi ein. Machinista öffnet die Steuerungsansicht auf beiden Farbdisplays. Plane beim ersten Start etwa zwei Minuten für die Speichererweiterung und einen möglichen Neustart ein.'))
    c=by['Record and overdub a Pattern'];step=c['steps'][1]
    c['steps'][1]=dict(mikro=text('Hold GRID and choose F3 GRID; NAV arrows select REC QUANT to enable or disable recording quantization. SHIFT + GRID still opens RECORD SETTINGS.', 'Halte GRID und wähle F3 GRID; NAV-Pfeile wählen REC QUANT zum Ein-/Ausschalten der Aufnahmequantisierung. SHIFT + GRID öffnet weiterhin RECORD SETTINGS.'),mk1=text('Hold GRID, choose display button 3 GRID and set REC QUANT with encoder 5. SHIFT + GRID still opens RECORD SETTINGS.','Halte GRID, wähle Displaytaste 3 GRID und stelle REC QUANT mit Encoder 5 ein. SHIFT + GRID öffnet weiterhin RECORD SETTINGS.'),mk2=text('Hold GRID, choose display button 3 GRID and set REC QUANT with encoder 5. SHIFT + GRID still opens RECORD SETTINGS.','Halte GRID, wähle Displaytaste 3 GRID und stelle REC QUANT mit Encoder 5 ein. SHIFT + GRID öffnet weiterhin RECORD SETTINGS.'),mk3=text('Hold SHIFT + FOLLOW to open GRID. Encoder 1 sets resolution; encoder 5 REC QUANT switches recording quantization independently of the editing grid. Hold REC for one second for recording length/grid preparation; release to return to recording.','Halte SHIFT + FOLLOW zum Öffnen von GRID. Encoder 1 stellt die Rasterweite ein; Encoder 5 REC QUANT schaltet die Aufnahmequantisierung unabhängig vom Bearbeitungsraster. Halte REC eine Sekunde für die Aufnahmevorbereitung mit Länge und Raster; beim Loslassen kehrst du zurück.'))
    c=by['Keyboard, scales and 16 velocities'];c['steps'][0]=dict(mikro=c['steps'][0],mk2=c['steps'][0],mk3=text('Press KEYBOARD or use SHIFT + PAD MODE to toggle melodic playing of the selected Sound. CHORDS toggles custom chords. Choose ROOT and SCALE as required.','KEYBOARD oder SHIFT + PAD MODE schaltet das melodische Spielen des gewählten Sounds um. CHORDS schaltet eigene Akkorde um. Wähle bei Bedarf ROOT und SCALE.'))
    c=by['Audio and controller settings']
    c['notes'][0][1]['mk3']=text('Display and pad preferences apply to this controller. System Info shows CPU/RAM, per-core CPU bars and storage.','Display- und Pad-Einstellungen gelten für diesen Controller. System Info zeigt CPU/RAM, CPU-Balken je Kern und Datenträger.')
    title,body=c['notes'][1]
    c['notes'][1]=(title,dict(mikro=body,mk1=body,mk2=body,mk3=text('CPU is averaged across cores. A single busy core can cause audio overruns.','CPU ist der Mittelwert aller Kerne. Ein einzelner ausgelasteter Kern kann Audioaussetzer verursachen.')))
    c['notes'][2][1]['mk3']=text('Use the physical interface knobs for gain and output level. Pads remain playable in Settings. RESET affects only this controller.','Nutze die Hardware-Regler für Gain und Ausgangspegel. Pads bleiben in Settings spielbar. RESET gilt nur für diesen Controller.')
    c['notes'].append((text('MK3 audio and MIDI','MK3 Audio und MIDI'),dict(mikro='',mk1='',mk2='',mk3=text('Choose the MK3 in AUDIO > INTERFACE. Main output uses channels 1/2; headphones use 3/4. Assign Cue and Sound/Group routes to the desired pair. Select Maschine MK3 MIDI 1 for DIN MIDI input/output. Hardware knobs set physical gain and output levels.','Wähle die MK3 unter AUDIO > INTERFACE. Main nutzt Kanal 1/2, der Kopfhörer 3/4. Weise Cue und Sound-/Group-Routen dem gewünschten Paar zu. Maschine MK3 MIDI 1 wählt DIN-MIDI-Ein-/Ausgang. Die Hardware-Regler stellen physische Verstärkung und Ausgangspegel ein.'))))


def mk3_text(value):
    """Resolve shared wording to MK3 hardware, after per-chapter overrides."""
    pairs=[('SHIFT + PLAY','SHIFT + TAP'),('GRID > STEP','GRID > GRID'),('GRID → STEP','GRID → GRID'),('SHIFT + CONTROL','SETTINGS'),('SHIFT + ALL','SHIFT + FILE'),('SHIFT + NOTE REPEAT','TAP'),('SHIFT + ENTER','TAP'),('SHIFT + GRID','SHIFT + FOLLOW'),('Press GRID','Press SHIFT + FOLLOW'),('Hold GRID','Hold SHIFT + FOLLOW'),('Drücke GRID','Drücke SHIFT + FOLLOW'),('Halte GRID','Halte SHIFT + FOLLOW'),('NAVIGATE','VARIATION'),('CONTROL returns','CHANNEL returns'),('CONTROL führt','CHANNEL führt'),('Use CONTROL','Use CHANNEL'),('Mit CONTROL','Mit CHANNEL'),('Press CONTROL','Press CHANNEL'),('Drücke CONTROL','Drücke CHANNEL'),('CONTROL to return','CHANNEL to return'),('großen Master-Encoder','4D-Encoder'),('large master encoder','4D encoder'),('master encoder','4D encoder'),('Master-Encoder','4D-Encoder'),('ENTER','4D PUSH'),('Plain ALL','The ALL selection action'),('ALL toggles','The displayed ALL action toggles'),('ALL wechselt','Die angezeigte ALL-Aktion wechselt'),('Plain ALL is selection','Die ALL-Aktion dient zur Auswahl'),('The MK2','The MK3'),('Die MK2','Die MK3'),('On MK2','On MK3'),('Auf MK2','Auf MK3')]
    for old,new in pairs:value=value.replace(old,new)
    return value
